-- À coller dans Supabase > SQL Editor > Run
create table if not exists drivers (id serial primary key, prenom text not null, nom text not null, role text default 'chauffeur', telephone text, vehicule_id int);
create table if not exists vehicles (id serial primary key, modele text not null, type text, carburant text, consommation numeric, capacite_kg int, volume_m3 numeric, autonomie_km int, annee int, immat text, reservoir_l numeric);
create table if not exists tournees (id serial primary key, driver_id int references drivers(id), vehicle_id int references vehicles(id), date date default current_date, statut text default 'prevue');
create table if not exists livraisons (id text primary key, tournee_id int references tournees(id) on delete cascade, ordre int, client text, adresse text, lat double precision, lon double precision, statut text default 'a_faire');

alter table drivers enable row level security;
drop policy if exists read_drivers on drivers;
create policy read_drivers on drivers for select using (true);
alter table vehicles enable row level security;
drop policy if exists read_vehicles on vehicles;
create policy read_vehicles on vehicles for select using (true);
alter table tournees enable row level security;
drop policy if exists read_tournees on tournees;
create policy read_tournees on tournees for select using (true);
alter table livraisons enable row level security;
drop policy if exists read_livraisons on livraisons;
create policy read_livraisons on livraisons for select using (true);
select setval('drivers_id_seq',100); select setval('vehicles_id_seq',100); select setval('tournees_id_seq',1);
